namespace BlazorApp.Services;

public class Notification
{
    public int Id { get; set; }
    public string Message { get; set; } = string.Empty;
    public DateTime Timestamp { get; set; }
}

public class NotificationService
{
    private int _nextId = 1;

    public Task<List<Notification>> GetInitialNotificationsAsync()
    {
        var notifications = new List<Notification>
        {
            new() { Id = _nextId++, Message = "Welcome to the app!", Timestamp = DateTime.UtcNow.AddMinutes(-10) },
            new() { Id = _nextId++, Message = "You have a new follower.", Timestamp = DateTime.UtcNow.AddMinutes(-5) },
            new() { Id = _nextId++, Message = "Your report is ready.", Timestamp = DateTime.UtcNow.AddMinutes(-1) },
        };
        return Task.FromResult(notifications);
    }

    public Task<List<Notification>> CheckForNewNotificationsAsync(int afterId)
    {
        var results = new List<Notification>();

        // Simulate a new notification arriving roughly every other poll
        if (Random.Shared.Next(2) == 0)
        {
            results.Add(new Notification
            {
                Id = Interlocked.Increment(ref _nextId),
                Message = $"New event at {DateTime.UtcNow:HH:mm:ss}",
                Timestamp = DateTime.UtcNow
            });
        }

        return Task.FromResult(results);
    }
}

